-- Cut-outs live in their own columns; the original art stays where it was.
--
-- Replacing `avatar` in place took the scenery out of the character sheet's
-- hero image too, which is not what that screen wants — it wants the full
-- illustration. Only the play screen's 2D layer needs a transparent PNG,
-- because only there is something drawn behind her.
alter table public.characters add column if not exists avatar_nobg text;
alter table public.character_costumes add column if not exists url_nobg text;
alter table public.character_costumes add column if not exists thumbnail_nobg text;

comment on column public.characters.avatar_nobg is
  'Background removed. The play screen 2D layer uses this; everything else uses `avatar`.';

-- Undo the in-place swap.
update public.characters set avatar = avatar_original
 where avatar_original is not null and avatar like '%/truemate/nobg/%';
update public.character_costumes set url = url_original
 where url_original is not null and url like '%/truemate/nobg/%';

-- Park the cut-outs in their own columns.
update public.characters c set avatar_nobg = v.u
  from (values ('0e40054f-6ed6-407c-afa9-36c8e723221d'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_0e40054f-6ed6-407c-afa9-36c8e723221d.png'),('6c35e0fc-915b-4422-8b46-92816472330f'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_6c35e0fc-915b-4422-8b46-92816472330f.png'),('9b0a4f5c-4f8e-4c9e-9b18-004000000004'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_9b0a4f5c-4f8e-4c9e-9b18-004000000004.png'),('9a8a2a8d-36df-40af-b287-8b749023e58f'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_9a8a2a8d-36df-40af-b287-8b749023e58f.png'),('2bbbb58e-63d9-4c00-b73b-5397ec92e1f2'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_2bbbb58e-63d9-4c00-b73b-5397ec92e1f2.png'),('d99530ec-f7ad-4d8f-935a-fbeaa4828b33'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_d99530ec-f7ad-4d8f-935a-fbeaa4828b33.png'),('8c5d26bb-f924-41d4-8d4c-015e6ad77a90'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_8c5d26bb-f924-41d4-8d4c-015e6ad77a90.png'),('ce5f74c2-81b3-4ffd-a561-e3d2d53bb29b'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_ce5f74c2-81b3-4ffd-a561-e3d2d53bb29b.png'),('36fdc274-753c-4173-a00f-a9a006d282fa'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_36fdc274-753c-4173-a00f-a9a006d282fa.png'),('47302891-105a-4076-953e-60425be2210f'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_47302891-105a-4076-953e-60425be2210f.png'),('bb9652ab-ce2e-484a-ad41-77fb6122faf0'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_bb9652ab-ce2e-484a-ad41-77fb6122faf0.png'),('5f01d7e4-4337-431b-8912-10da06e5bf39'::uuid,'https://pub-45d710f6a77246d8825015e13deb5899.r2.dev/truemate/nobg/char_5f01d7e4-4337-431b-8912-10da06e5bf39.png'),('037332ab-e96c-48db-8935-b8a1b120344e'::uuid,'https: